window.addEventListener('load', function(){
  if(!window.gsap || !window.ScrollTrigger) return;
  if(window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  gsap.registerPlugin(ScrollTrigger);
  // NOTE: never animate the hero visual's OPACITY here. rAF throttles in
  // background tabs and can freeze an opacity tween mid-flight, leaving the
  // dashboard washed-out. Animate a gentle slide only; the visual is always
  // fully opaque and readable even if a tween is interrupted.
  var vis = document.querySelector('.ihero__visual');
  var viz = document.querySelector('.ihero__viz');
  if(viz){
    gsap.from(viz, {y:24, duration:.8, ease:'power3.out', clearProps:'transform'});
  }
  if(vis){
    gsap.to(vis, {yPercent:-5, ease:'none', scrollTrigger:{trigger:vis, start:'top 80%', end:'bottom top', scrub:0.6}});
  }
});

(function(){
  function initSearch(inputId, listId, cardsContainerId, itemSelector, getInfoFn) {
    var inputEl = document.getElementById(inputId);
    var listEl = document.getElementById(listId);
    var cardsContainer = document.getElementById(cardsContainerId);
    if (!inputEl || !listEl || !cardsContainer) return;

    var cardEls = Array.from(cardsContainer.querySelectorAll(itemSelector));
    var itemsData = cardEls.map(function(card) {
      return getInfoFn(card);
    });

    function renderList(items) {
      if (!items || items.length === 0) {
        listEl.innerHTML = '<div style="font-size:0.88rem;color:var(--muted);padding:4px 0;">No results found</div>';
        return;
      }
      var html = '';
      items.forEach(function(item) {
        html += '<div><a href="' + item.url + '">' + item.title + '</a></div>';
      });
      listEl.innerHTML = html;
    }

    renderList(itemsData.slice(0, 3));

    inputEl.addEventListener('input', function(e) {
      var q = (e.target.value || '').trim().toLowerCase();
      if (!q) {
        renderList(itemsData.slice(0, 3));
      } else {
        var filtered = itemsData.filter(function(item) {
          return item.title.toLowerCase().indexOf(q) !== -1 ||
                 (item.category && item.category.toLowerCase().indexOf(q) !== -1) ||
                 (item.description && item.description.toLowerCase().indexOf(q) !== -1);
        });
        renderList(filtered);
      }
    });
  }

  function start() {
    initSearch(
      'blog-search-input',
      'blog-sidebar-list',
      'blog-cards-grid',
      '.artcard',
      function(card) {
        var h = card.querySelector('h3');
        var c = card.querySelector('.art-cat');
        var p = card.querySelector('p');
        return {
          url: card.getAttribute('href') || '#',
          title: h ? h.textContent.trim() : '',
          category: c ? c.textContent.trim() : '',
          description: p ? p.textContent.trim() : ''
        };
      }
    );

    initSearch(
      'cs-search-input',
      'cs-sidebar-list',
      'cs-cards-grid',
      '.wcard',
      function(card) {
        var h = card.querySelector('h3');
        var tag = card.querySelector('.wtag');
        var theme = card.querySelector('.wtheme');
        var p = card.querySelector('p');
        var cat = (tag ? tag.textContent.trim() : '') + ' ' + (theme ? theme.textContent.trim() : '');
        return {
          url: card.getAttribute('href') || '#',
          title: h ? h.textContent.trim() : '',
          category: cat.trim(),
          description: p ? p.textContent.trim() : ''
        };
      }
    );
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', start);
  } else {
    start();
  }
})();
